// STEP 2: send each new email + its PDF attachments to the Netlify app.
// >>> EDIT THESE TWO LINES <<<
const SITE_URL = 'https://YOUR-SITE.netlify.app';
const INTAKE_SECRET = 'PASTE-YOUR-INTAKE_SECRET-HERE';

const results = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const mail = items[i].json;
  const attachments = [];
  for (const key of Object.keys(items[i].binary || {})) {
    const meta = items[i].binary[key];
    const isPdf = (meta.mimeType || '').includes('pdf') || (meta.fileName || '').toLowerCase().endsWith('.pdf');
    if (!isPdf) continue;
    const buf = await this.helpers.getBinaryDataBuffer(i, key);
    attachments.push({ filename: meta.fileName || `${key}.pdf`, contentType: 'application/pdf', base64: buf.toString('base64') });
  }
  const from = mail.from?.value?.[0] || {};
  const payload = {
    messageId: mail.messageId || mail.id,
    from: from.address || mail.from?.text || 'unknown',
    fromName: from.name || from.address || '',
    subject: mail.subject || '',
    body: (mail.text || '').slice(0, 8000),
    receivedAt: mail.date || new Date().toISOString(),
    attachments,
  };
  const full = await this.helpers.httpRequest({
    method: 'POST', url: `${SITE_URL}/api/intake`, json: true, body: payload,
    headers: { 'x-intake-secret': INTAKE_SECRET }, timeout: 60000,
    returnFullResponse: true, ignoreHttpStatusErrors: true,
  });
  if (full.statusCode >= 400) {
    throw new Error(`Website said ${full.statusCode}: ${JSON.stringify(full.body).slice(0, 500)}`);
  }
  const res = full.body;
  results.push({ json: { subject: payload.subject, from: payload.from, pdfs: attachments.length, result: res } });
}
return results.length ? results : [{ json: { note: 'no new emails' } }];

// STEPS 3 + 4: run the AI agents on everything in the queue, then write the ops digest.
// >>> EDIT THESE TWO LINES (same values as step 2) <<<
const SITE_URL = 'https://YOUR-SITE.netlify.app';
const INTAKE_SECRET = 'PASTE-YOUR-INTAKE_SECRET-HERE';

const call = async (path) => {
  const full = await this.helpers.httpRequest({
    method: 'POST', url: `${SITE_URL}/api/${path}`, json: true, body: {},
    headers: { 'x-intake-secret': INTAKE_SECRET }, timeout: 65000,
    returnFullResponse: true, ignoreHttpStatusErrors: true,
  });
  if (full.statusCode >= 400) {
    throw new Error(`Website said ${full.statusCode}: ${JSON.stringify(full.body).slice(0, 500)}`);
  }
  return full.body;
};
const started = Date.now();
const done = [];
while (Date.now() - started < 4 * 60 * 1000) {   // stop after 4 minutes; the next run continues
  const r = await call('work');
  if (r.did === 'idle') break;
  if (r.did.startsWith('error:')) { done.push(r.did); break; }
  if (r.did.startsWith('waiting')) { await new Promise((res) => setTimeout(res, 3000)); continue; }
  done.push(r.did);
}
let digest = null;
if (done.length) digest = await call('digest');
return [{ json: { agentRuns: done.length, steps: done, digest } }];
